(7499599, 1195149, 19825, '<td valign="top">Interesting framing</td>', 'Interesting framing', '2017-02-15 08:35:39.000000', NULL, 1),
(7499600, 1195318, 19825, '<td valign="top">Nicely disorienting.</td>', 'Nicely disorienting.', '2017-02-15 08:36:23.000000', NULL, 1),
(7499619, 1195086, 163081, '<td valign="top">very nice. 8 from me</td>', 'very nice. 8 from me', '2017-02-15 09:46:58.000000', NULL, 1),
(7499625, 1194915, 47974, '<td valign="top">If you had used peppers that are actually hot this would have been a much better photograph.  I just can''t buy the Hot Peppers part from normal every day bell peppers.</td>', 'If you had used peppers that are actually hot this would have been a much better photograph.  I just can''t buy the Hot Peppers part from normal every day bell peppers.', '2017-02-15 10:49:46.000000', NULL, 1),
(7499626, 1195385, 47974, '<td valign="top">Something about his just looks fake................</td>', 'Something about his just looks fake................', '2017-02-15 10:50:51.000000', NULL, 1),
(7499628, 1195427, 86447, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2017-02-15 10:53:36.000000', NULL, 1),
(7499629, 1195228, 86447, '<td valign="top">Oh!  How charming!<br/> <br/>I wish the upper board were perfectly level for anal people like me... but golly!  The rest is so fun and wonderful!</td>', 'Oh!  How charming! I wish the upper board were perfectly level for anal people like me... but golly!  The rest is so fun and wonderful!', '2017-02-15 10:55:13.000000', NULL, 1),
(7499630, 1195409, 86447, '<td valign="top">Way cool!</td>', 'Way cool!', '2017-02-15 10:56:09.000000', NULL, 1),
(7499631, 1195434, 86447, '<td valign="top">Lovely!</td>', 'Lovely!', '2017-02-15 10:56:20.000000', NULL, 1),
(7499632, 1195435, 86447, '<td valign="top">Perfect title for a fun, and well done, piece of art!</td>', 'Perfect title for a fun, and well done, piece of art!', '2017-02-15 10:56:56.000000', NULL, 1),
(7499634, 1194122, 86447, '<td valign="top">Seems like the items would be closer together on the scene if I were making waffles... (and that might make the image more cohesive, I think)  but wow!  What a fabulous job you''ve done of it all!</td>', 'Seems like the items would be closer together on the scene if I were making waffles... (and that might make the image more cohesive, I think)  but wow!  What a fabulous job you''ve done of it all!', '2017-02-15 10:58:35.000000', NULL, 1),
(7499635, 1194741, 86447, '<td valign="top">Ha!  Brilliant!</td>', 'Ha!  Brilliant!', '2017-02-15 10:58:50.000000', NULL, 1),
(7499636, 1195385, 86447, '<td valign="top">Fabulous shot of the lion!  If you add some dark places under her feet, she''d feel more "grounded" to the viewer, I think.</td>', 'Fabulous shot of the lion!  If you add some dark places under her feet, she''d feel more "grounded" to the viewer, I think.', '2017-02-15 11:00:46.000000', NULL, 1),
(7499637, 1195149, 86447, '<td valign="top">Really cool!   WEll done!</td>', 'Really cool!   WEll done!', '2017-02-15 11:01:56.000000', NULL, 1),
(7499638, 1195300, 86447, '<td valign="top">How adorable!!</td>', 'How adorable!!', '2017-02-15 11:02:21.000000', NULL, 1),
(7499639, 1195302, 86447, '<td valign="top">Very pretty!</td>', 'Very pretty!', '2017-02-15 11:02:47.000000', NULL, 1),
(7499641, 1195360, 124815, '<td valign="top">I looked on two monitors at this image. Milano in all its splendor. I cannot figure out if you worked on a photo...at this point, I just want to believe that it is not a found image torn from an old album.<br/>Even so, totally captivating</td>', 'I looked on two monitors at this image. Milano in all its splendor. I cannot figure out if you worked on a photo...at this point, I just want to believe that it is not a found image torn from an old album.Even so, totally captivating', '2017-02-15 11:53:50.000000', NULL, 1),
(7499643, 1195149, 124815, '<td valign="top">Effective - just wish that the future will be so neatly organized!</td>', 'Effective - just wish that the future will be so neatly organized!', '2017-02-15 11:56:00.000000', NULL, 1),
(7499644, 1195012, 124815, '<td valign="top">Unreal!</td>', 'Unreal!', '2017-02-15 11:56:52.000000', NULL, 1),
(7499646, 1195335, 124815, '<td valign="top">Like the crying icons. <br/>I mind a lot what is in my opinion the unnecessary tree - in a thumbnail you lose it and it''s so much more effective - I imagined that you wanted the bird to fly from it but there is no need to be so literal.<br/>Painterly tears.</td>', 'Like the crying icons. I mind a lot what is in my opinion the unnecessary tree - in a thumbnail you lose it and it''s so much more effective - I imagined that you wanted the bird to fly from it but there is no need to be so literal.Painterly tears.', '2017-02-15 12:04:01.000000', NULL, 1),
(7499647, 1195374, 124815, '<td valign="top">So much like a romantic German painting. Great color palette</td>', 'So much like a romantic German painting. Great color palette', '2017-02-15 12:08:55.000000', NULL, 1),
(7499649, 1195439, 124815, '<td valign="top">I am totally fascinated by the upper left corner! It can be an image on its own.</td>', 'I am totally fascinated by the upper left corner! It can be an image on its own.', '2017-02-15 12:10:35.000000', NULL, 1),
(7499651, 1195330, 124815, '<td valign="top">It resonates forever like a tune you can''t take away form your head</td>', 'It resonates forever like a tune you can''t take away form your head', '2017-02-15 12:11:27.000000', NULL, 1),
(7499655, 1194392, 124815, '<td valign="top">One extraordinary scary image</td>', 'One extraordinary scary image', '2017-02-15 12:12:53.000000', NULL, 1),
(7499660, 1195443, 124815, '<td valign="top">It reminds me of the etchings of the late ''70s<br/>Eloquent</td>', 'It reminds me of the etchings of the late ''70sEloquent', '2017-02-15 12:16:35.000000', NULL, 1),
(7499663, 1195364, 124815, '<td valign="top">Hell on earth</td>', 'Hell on earth', '2017-02-15 12:18:43.000000', NULL, 1),
(7499664, 1195122, 124815, '<td valign="top">Something is so out of proportion, although being real, that it makes for a fascinating image</td>', 'Something is so out of proportion, although being real, that it makes for a fascinating image', '2017-02-15 12:20:23.000000', NULL, 1),
(7499665, 1195441, 124815, '<td valign="top">the sixth sense</td>', 'the sixth sense', '2017-02-15 12:21:12.000000', NULL, 1),
(7499666, 1194338, 124815, '<td valign="top">yes, a brave new world</td>', 'yes, a brave new world', '2017-02-15 12:21:59.000000', NULL, 1),
(7499698, 1195086, 114225, '<td valign="top">Eliminate that selective saturation and you would have a print worthy image, in my opinion.</td>', 'Eliminate that selective saturation and you would have a print worthy image, in my opinion.', '2017-02-15 13:38:53.000000', NULL, 1),
(7499700, 1195343, 114225, '<td valign="top">Overall, I really like your idea. I would like to offer a few constructive criticisms:<br/>1. There are some things that are not sharp. With this image, it cries out to me "I want it all in tack sharpness"<br/>2. The tea cup is bothering me, because it doesn''t feel centered. I''m guessing you shot with a wide angle, so even if you are perfectly centered, the distortion is hindering. Maybe see if you could do this with 85mm or more.</td>', 'Overall, I really like your idea. I would like to offer a few constructive criticisms:1. There are some things that are not sharp. With this image, it cries out to me "I want it all in tack sharpness"2. The tea cup is bothering me, because it doesn''t feel centered. I''m guessing you shot with a wide angle, so even if you are perfectly centered, the distortion is hindering. Maybe see if you could do this with 85mm or more.', '2017-02-15 13:42:22.000000', NULL, 1),
(7499702, 1195228, 114225, '<td valign="top">Overall, I really like it. I think it would be a great exercise to try to have dark wood in the background instead of pitch black.<br/> <br/>Also, I think maybe your lens has a little pincushion distortion. Should be easy to fix that in post and get nice straight lines.</td>', 'Overall, I really like it. I think it would be a great exercise to try to have dark wood in the background instead of pitch black. Also, I think maybe your lens has a little pincushion distortion. Should be easy to fix that in post and get nice straight lines.', '2017-02-15 13:45:25.000000', NULL, 1),
(7499703, 1194915, 114225, '<td valign="top">Hot idea (pun intended)!<br/> <br/>One thing you should try: a polarizer. The white (actually bluish, because your white balance is a little off) reflections really stick out at me. A polarizer should cut those down.</td>', 'Hot idea (pun intended)! One thing you should try: a polarizer. The white (actually bluish, because your white balance is a little off) reflections really stick out at me. A polarizer should cut those down.', '2017-02-15 13:47:32.000000', NULL, 1),
(7499704, 1194154, 114225, '<td valign="top">The water is great. The horizon is great. The sky is so over contrasted that it looks terrible (sorry).</td>', 'The water is great. The horizon is great. The sky is so over contrasted that it looks terrible (sorry).', '2017-02-15 13:48:43.000000', NULL, 1),
(7499705, 1195065, 114225, '<td valign="top">A constructive criticisms for your image.<br/> <br/>1. Why is there so much space in the foreground? That doesn''t add anything to your photo. Your subject is obviously the people, but with so much foreground space, they become less of a subject than the building. Crop just under the feet for a stronger image.<br/> <br/>2. The sky showing through the windows is unnaturally greyish. Keep it more natural, even if that means it''s a bit blown out.</td>', 'A constructive criticisms for your image. 1. Why is there so much space in the foreground? That doesn''t add anything to your photo. Your subject is obviously the people, but with so much foreground space, they become less of a subject than the building. Crop just under the feet for a stronger image. 2. The sky showing through the windows is unnaturally greyish. Keep it more natural, even if that means it''s a bit blown out.', '2017-02-15 13:50:59.000000', NULL, 1),
(7499736, 1194392, 30861, '<td valign="top">Don''t talk back?</td>', 'Don''t talk back?', '2017-02-15 15:46:05.000000', NULL, 1),
(7499817, 1195335, 112739, '<td valign="top">Haven''t been moved by a photo as much as this one lately.</td>', 'Haven''t been moved by a photo as much as this one lately.', '2017-02-15 17:53:39.000000', NULL, 1),
(7500088, 1195301, 183150, '<td valign="top">I do not always like this effect, but your use of it here elevates this photo to art.</td>', 'I do not always like this effect, but your use of it here elevates this photo to art.', '2017-02-16 11:45:11.000000', NULL, 1),
