(7500431, 1195122, 28742, '<td valign="top">I bet that dude with the stick could escape if he wanted to. :P</td>', 'I bet that dude with the stick could escape if he wanted to. :P', '2017-02-17 12:29:59.000000', NULL, 1),
(7501030, 1195385, 150202, '<td valign="top">The different elements seem very separated, giving it an unnatural look, and the sunset looks off level. The colors in they sky are really beautiful.</td>', 'The different elements seem very separated, giving it an unnatural look, and the sunset looks off level. The colors in they sky are really beautiful.', '2017-02-20 07:11:22.000000', NULL, 1),
(7501031, 1195274, 150202, '<td valign="top">Nice composition, but a little too bright or saturated for me.</td>', 'Nice composition, but a little too bright or saturated for me.', '2017-02-20 07:12:27.000000', NULL, 1),
(7501033, 1195012, 150202, '<td valign="top">The cars seem like the focal point instead of the waterfall, cropping them might have changed that. The dark colors near the falls look really nice.</td>', 'The cars seem like the focal point instead of the waterfall, cropping them might have changed that. The dark colors near the falls look really nice.', '2017-02-20 07:15:48.000000', NULL, 1),
(7501034, 1195240, 150202, '<td valign="top">The blur doesn''t seem to indicate direction, which I think might give better sense of flight.I like the softness it has.</td>', 'The blur doesn''t seem to indicate direction, which I think might give better sense of flight.I like the softness it has.', '2017-02-20 07:18:40.000000', NULL, 1),
(7501037, 1195438, 150202, '<td valign="top">I like how the background is nicely blurred, but the foreground could use more sharpness maybe.</td>', 'I like how the background is nicely blurred, but the foreground could use more sharpness maybe.', '2017-02-20 07:23:32.000000', NULL, 1),
(7501050, 1195427, 114225, '<td valign="top">Very nice light and setup.</td>', 'Very nice light and setup.', '2017-02-20 10:21:47.000000', NULL, 1),
