(7501557, 1195427, 37858, '<td valign="top">Another beautiful image, Mary Ann.  Congrats on the ribbon.  I''m beginning to intuitively know your style when I see it, and I always appreciate your offering.</td>', 'Another beautiful image, Mary Ann.  Congrats on the ribbon.  I''m beginning to intuitively know your style when I see it, and I always appreciate your offering.', '2017-02-22 03:02:47.000000', NULL, 0),
(7501570, 1195149, 182284, '<td valign="top">Well done Judi, I gave you a 10 on this. Congratulations!</td>', 'Well done Judi, I gave you a 10 on this. Congratulations!', '2017-02-22 04:35:45.000000', NULL, 0),
