(7502392, 1195410, 182284, '<td valign="top">Actually I sharpened this photo only once and it was just a general sharpen. I touched up the yellow in one spot on the yellow part. This flower looks like glass anyway. This was a challenge where everything goes but it''s judged like a minimal photo. OH! WELL!</td>', 'Actually I sharpened this photo only once and it was just a general sharpen. I touched up the yellow in one spot on the yellow part. This flower looks like glass anyway. This was a challenge where everything goes but it''s judged like a minimal photo. OH! WELL!', '2017-02-26 19:54:26.000000', NULL, 0),
(7502869, 1195086, 37858, '<td valign="top">Very well done.  Like others, I am not a fan of the selective color.  In this instance, though, it works better than most. Matrix is a perfect title for this image, too.</td>', 'Very well done.  Like others, I am not a fan of the selective color.  In this instance, though, it works better than most. Matrix is a perfect title for this image, too.', '2017-03-01 04:43:41.000000', NULL, 0);
